import type { Locale } from "@/app/i18n/config";
import { ApiRequestError, type ScanAccessMode } from "@/app/lib/api";
import { authorizedFetch } from "@/app/lib/session";

/**
 * Scan reports, generated by the backend.
 *
 * The backend builds one document from the stored results and renders it in
 * every format, so the preview (HTML) shows exactly what the downloaded file
 * holds. Account scan reports are served to their owner only; free scan
 * reports are public by scan id, like the scan itself.
 *
 * The backend writes the report's labels in the interface language; test
 * names and messages come from the engine and stay in English.
 */

export const REPORT_FORMATS = ["pdf", "html", "md", "sarif"] as const;
export type ReportFormat = (typeof REPORT_FORMATS)[number];

export interface ReportRequestOptions {
  mode: ScanAccessMode;
  format: ReportFormat;
  lang: Locale;
  signal?: AbortSignal;
}

export interface ScanReport {
  blob: Blob;
  filename: string;
}

function reportPath(scanId: string, mode: ScanAccessMode, format: ReportFormat, lang: Locale): string {
  const base = mode === "premium" ? "/api/scans" : "/api/freescans";
  const query = new URLSearchParams({ format, lang });
  return `${base}/${encodeURIComponent(scanId)}/report?${query}`;
}

/** The name the backend gave the file, or one built the same way. */
function filenameFrom(response: Response, scanId: string, format: ReportFormat): string {
  const disposition = response.headers.get("content-disposition") ?? "";
  const match = /filename\*?=(?:UTF-8'')?"?([^";]+)"?/i.exec(disposition);
  let name = "";
  try {
    name = match ? decodeURIComponent(match[1]).trim() : "";
  } catch {
    // A malformed escape: fall back to our own name.
  }
  // Only a bare file name: anything with a path in it is not ours to honour.
  return name && !/[\\/]/.test(name) ? name : `antiginx-report-${scanId}.${format}`;
}

async function errorFrom(response: Response): Promise<ApiRequestError> {
  const payload = (await response.json().catch(() => null)) as { error?: unknown; code?: unknown } | null;
  const message =
    typeof payload?.error === "string" ? payload.error : `Failed to generate report (HTTP ${response.status})`;
  // The backend's own code (SCAN_NOT_FINISHED, SCAN_NOT_FOUND, …) says more than the status.
  const code = typeof payload?.code === "string" ? payload.code : `HTTP_${response.status}`;
  return new ApiRequestError(message, { status: response.status, code });
}

export async function fetchScanReport(scanId: string, options: ReportRequestOptions): Promise<ScanReport> {
  const { mode, format, lang, signal } = options;
  const path = reportPath(scanId, mode, format, lang);
  const init: RequestInit = { method: "GET", signal };

  let response: Response;
  try {
    // Free scans stay anonymous, so they never touch the session store.
    response = mode === "premium" ? await authorizedFetch(path, init) : await fetch(path, init);
  } catch (error) {
    if (signal?.aborted) throw error;
    throw new ApiRequestError("Cannot connect to scanner service", { code: "NETWORK_ERROR", cause: error });
  }

  if (!response.ok) throw await errorFrom(response);

  return { blob: await response.blob(), filename: filenameFrom(response, scanId, format) };
}

/** Hands the file to the browser's download. */
export function saveReport({ blob, filename }: ScanReport) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  // Revoked on the next turn: Safari starts the download asynchronously.
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** Which message to show for a failed report request. */
export type ReportError = "notFinished" | "notFound" | "network" | "rateLimited" | "server" | "unexpected";

export function reportErrorOf(error: unknown): ReportError {
  if (!(error instanceof ApiRequestError)) {
    return error instanceof TypeError ? "network" : "unexpected";
  }
  if (error.code === "NETWORK_ERROR") return "network";
  if (error.code === "SCAN_NOT_FINISHED") return "notFinished";
  if (error.status === 404) return "notFound";
  if (error.status === 429) return "rateLimited";
  if (error.status && error.status >= 500) return "server";
  return "unexpected";
}
